import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`cro-audit`,heroTitle:`Improve your website conversion rate`,heroSubtitle:`Perplexity Computer visits your site, benchmarks against UX best practices, and delivers a prioritized list of conversion fixes — automatically.`,inputUrlCta:`Audit my site`,inputUrlPrefill:`Go to {url} and run a full conversion rate optimization audit. Visit key landing pages, product pages, and checkout flows. Benchmark against UX best practices for CTAs, forms, page speed, and mobile experience. Identify the biggest conversion bottlenecks and estimate their revenue impact. Deliver a prioritized fix list with specific recommendations for each issue.`,heroOverlaySteps:[`Visiting key pages, forms, CTAs, and checkout flows`,`Benchmarking against UX and conversion best practices`,`Identifying bottlenecks and estimating revenue impact`,`Prioritized fix list with specific recommendations`],generatingSteps:[`Connecting to {url} to map your site structure and key pages`,`Designing an agent to audit CTAs, forms, page speed, and mobile UX`,`Configuring conversion benchmarks and revenue impact estimates`,`Setting up report generation for prioritized fix list and recommendations`],featureSectionTitle:`From audit to more conversions`,featureCardTitles:[`Connects to your analytics stack`,`Fixes you can ship today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Analytics, Search Console, Ahrefs — Computer plugs into your tools so audits are backed by real traffic and behavior data.`,`CTA rewrites. Form simplifications. Speed fixes. Computer delivers specific, actionable changes ranked by expected impact.`],capabilitySectionTitle:`Your CRO team, on demand`,capabilitySectionSubtitle:`Enter your URL, get back a conversion optimization plan.`,capabilityCards:[{title:`Full Site Review`,description:`Computer visits your landing pages, product pages, and checkout flows — flagging issues that hurt conversions.`},{title:`Conversion Benchmarks`,description:`Computer compares your CTAs, forms, and page speed against industry best practices — and shows where you fall short.`},{title:`Bottleneck Analysis`,description:`Computer identifies where visitors drop off and estimates the revenue impact of each issue.`},{title:`Prioritized Fix List`,description:`Computer delivers specific recommendations ranked by effort and expected conversion lift — ready for your dev team.`},{title:`Knows Your Site`,description:`Computer remembers your site structure, past audits, and fix history — so every audit builds on what came before.`},{title:`Ongoing Monitoring`,description:`Computer watches your key pages for speed regressions, broken forms, and UX issues — and alerts you when something breaks.`}]});export{t as default};
